			Map.entry("env:OPT_X64DBG_EXE", new PathIsFile(Path.of("x64dbg.exe"))),
			Map.entry("env:OPT_PYTHON_EXE",
				new PathIsFile(Path.of(getPythonCmd()))))))
{
			checkResult(result);
		}
	}

